mapper.select:
   SELECT r.id,r.appointment_id AS appointmentId,a.appointment_no AS appointmentNo,c.name AS customerName,r.type,r.content,r.status,r.result,r.version,r.created_at AS createdAt FROM customer_request r JOIN appointment a ON r.appointment_id=a.id JOIN customer c ON r.customer_id=c.id WHERE 1=1 
   AND r.customer_id=#{customer}
ORDER BY r.id DESC LIMIT #{size} OFFSET #{offset}
